export default class TreeOfThoughtVoting {
  constructor(agents) {
    this.agents = agents;
  }

  evaluateOptions(options) {
    const scores = options.map(option => {
      return this.agents.reduce((score, agent) => {
        const confidence = agent.evaluate(option);
        return score + confidence * agent.weight;
      }, 0);
    });

    const bestOptionIndex = scores.indexOf(Math.max(...scores));
    return options[bestOptionIndex];
  }
}